cat > "$install_root/bin/kite-codex-upstream-proxy" <<'KITE_CODEX_PROXY'
#!/usr/bin/env node
'use strict';
const http = require('http');
const https = require('https');
const upstream = new URL(process.env.KITE_CODEX_UPSTREAM || '');
if (!['http:', 'https:'].includes(upstream.protocol)) throw new Error('unsupported_upstream_protocol');
const port = Number(process.env.KITE_CODEX_PROXY_PORT || '4454');
const hopByHop = new Set(['connection', 'keep-alive', 'proxy-authenticate', 'proxy-authorization', 'te', 'trailer', 'transfer-encoding', 'upgrade']);
const cleanHeaders = (headers) => Object.fromEntries(Object.entries(headers).filter(([name]) => !hopByHop.has(name.toLowerCase())));
const basePath = upstream.pathname.replace(/\/+$/, '');
const transport = upstream.protocol === 'https:' ? https : http;
const server = http.createServer((request, response) => {
  const incomingPath = request.url || '/';
  const suffix = incomingPath.startsWith('/') ? incomingPath : `/${incomingPath}`;
  const headers = cleanHeaders(request.headers);
  headers.host = upstream.host;
  const outgoing = transport.request({
    protocol: upstream.protocol,
    hostname: upstream.hostname,
    port: upstream.port || undefined,
    method: request.method,
    path: `${basePath}${suffix}`,
    headers,
  }, (upstreamResponse) => {
    response.writeHead(upstreamResponse.statusCode || 502, cleanHeaders(upstreamResponse.headers));
    upstreamResponse.pipe(response);
  });
  outgoing.on('error', (error) => {
    if (!response.headersSent) response.writeHead(502, {'content-type': 'application/json'});
    response.end(JSON.stringify({error: {message: 'upstream_transport_error', code: error.code || 'UNKNOWN'}}));
  });
  request.on('aborted', () => outgoing.destroy());
  request.pipe(outgoing);
});
server.on('clientError', (_error, socket) => socket.end('HTTP/1.1 400 Bad Request\r\n\r\n'));
server.listen(port, '127.0.0.1');
KITE_CODEX_PROXY
cat > "$install_root/bin/kite-codex-acp" <<'KITE_CODEX_ACP'
#!/usr/bin/env bash
set -eu
upstream_file='/workspace/.kf/secrets/kite.codex-relay-upstream'
api_key_file='/workspace/.kf/secrets/kite.codex-relay-api-key'
relay_log='/workspace/.kf/logs/codex-responses-relay.log'
if [ ! -s "$upstream_file" ]; then exec codex-acp "$@"; fi
relay_pid=''
proxy_pid=''
stop_pid() {
  target_pid="$1"
  if [ -n "$target_pid" ] && kill -0 "$target_pid" 2>/dev/null; then
    kill "$target_pid" 2>/dev/null || true
    wait "$target_pid" 2>/dev/null || true
  fi
}
cleanup() {
  stop_pid "$relay_pid"
  stop_pid "$proxy_pid"
}
trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
upstream="$(tr -d '\r\n' < "$upstream_file")"
if [ -z "$upstream" ]; then echo 'Codex relay upstream missing' >&2; exit 2; fi
if [ -s "$api_key_file" ]; then export CODEX_RELAY_API_KEY="$(cat "$api_key_file")"; else unset CODEX_RELAY_API_KEY; fi
mkdir -p "$(dirname "$relay_log")"
: > "$relay_log"
chmod 600 "$relay_log"
case "$upstream" in
  https://*)
    launcher_path="$(readlink -f "$0")"
    proxy_script="$(dirname "$launcher_path")/kite-codex-upstream-proxy"
    KITE_CODEX_UPSTREAM="$upstream" KITE_CODEX_PROXY_PORT=4454 node "$proxy_script" >> "$relay_log" 2>&1 &
    proxy_pid=$!
    ready=0
    attempts=0
    while [ "$attempts" -lt 120 ]; do
      if ! kill -0 "$proxy_pid" 2>/dev/null; then echo 'Codex upstream proxy exited during startup' >&2; exit 2; fi
      if (exec 3<>/dev/tcp/127.0.0.1/4454) 2>/dev/null; then exec 3>&-; exec 3<&-; ready=1; break; fi
      attempts=$((attempts + 1))
      sleep 0.1
    done
    if [ "$ready" -ne 1 ]; then echo 'Codex upstream proxy startup timed out' >&2; exit 2; fi
    export CODEX_RELAY_UPSTREAM='http://127.0.0.1:4454'
    ;;
  *) export CODEX_RELAY_UPSTREAM="$upstream" ;;
esac
codex-relay --bind 127.0.0.1 --port 4453 >> "$relay_log" 2>&1 &
relay_pid=$!
ready=0
attempts=0
while [ "$attempts" -lt 120 ]; do
  if ! kill -0 "$relay_pid" 2>/dev/null; then echo 'Codex relay exited during startup' >&2; exit 2; fi
  if (exec 3<>/dev/tcp/127.0.0.1/4453) 2>/dev/null; then exec 3>&-; exec 3<&-; ready=1; break; fi
  attempts=$((attempts + 1))
  sleep 0.1
done
if [ "$ready" -ne 1 ]; then echo 'Codex relay startup timed out' >&2; exit 2; fi
codex-acp "$@"
KITE_CODEX_ACP
chmod 755 "$install_root/bin/kite-codex-upstream-proxy" "$install_root/bin/kite-codex-acp"
